package app.quietagent.workspace;
public final class CsvTableParserTests{private static void ok(boolean v,String m){if(!v)throw new AssertionError(m);}public static void main(String[]x)throws Exception{CsvTableParser.Result r=CsvTableParser.parse("name,note\r\n\"A, B\",\"line1\nline2\"\r\nC,\"quote \"\"ok\"\"\"",20,10);ok(r.rows.size()==3,"rows");ok(r.rows.get(1).get(0).equals("A, B"),"comma");ok(r.rows.get(1).get(1).equals("line1\nline2"),"newline");ok(r.rows.get(2).get(1).equals("quote \"ok\""),"quote");CsvTableParser.Result t=CsvTableParser.parse("a\n1\n2",2,2);ok(t.rows.size()==2&&t.truncated,"truncate");System.out.println("CsvTableParserTests OK");}}
